// Generated by vibelang from src/home/projects/add.ts; the migrate flow writes it again with each batch.
export async function addProjects(context, directories) {
    const projects = await Promise.all(directories.map((directory) => context.projects.add(directory)));
    // Additions finish in any order; the first directory is the one the caller opens.
    if (projects[0])
        context.projects.touch(projects[0].worktree);
    return projects[0];
}
